func TestFormatVersion(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		version string
		commit  string
		want    string
	}{
		{"release passes through", "v0.0.1", "abc1234", "v0.0.1"},
		{"nightly passes through", "v0.5.1-nightly.202604101200.abc1234", "abc1234", "v0.5.1-nightly.202604101200.abc1234"},
		{"dev with commit appends digest", "dev", "abc1234", "dev (abc1234)"},
		{"dev with unknown commit stays bare", "dev", "unknown", "dev"},
		{"dev with empty commit stays bare", "dev", "", "dev"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := FormatVersion(tt.version, tt.commit); got != tt.want {
				t.Errorf("FormatVersion(%q, %q) = %q, want %q", tt.version, tt.commit, got, tt.want)
			}
		})
	}
}

